def _criar_gatilhos_de_imutabilidade() -> None:
    """Imutabilidade garantida pelo banco, não por disciplina de código.

    - `consentimentos` e `ciencias`: `UPDATE` sempre falha. `DELETE` só é aceito quando o
      pai (cliente ou usuário) já não existe — ou seja, apenas em cascata do direito de
      eliminação (LGPD, art. 18, VI). Uma exclusão isolada é recusada.
    - `termos`: uma versão publicada não muda. Só a marcação de vigência pode ser alterada.
    """
    op.execute(
        """
        CREATE FUNCTION consentimentos_imutaveis() RETURNS trigger AS $$
        BEGIN
            IF TG_OP = 'UPDATE' THEN
                RAISE EXCEPTION
                    'consentimentos sao imutaveis: registre uma nova decisao em vez de alterar o historico'
                    USING ERRCODE = 'restrict_violation';
            END IF;

            IF EXISTS (SELECT 1 FROM clientes WHERE id = OLD.cliente_id)
               AND EXISTS (SELECT 1 FROM usuarios WHERE id = OLD.usuario_id) THEN
                RAISE EXCEPTION
                    'consentimentos so podem ser excluidos junto com o cliente ou a conta'
                    USING ERRCODE = 'restrict_violation';
            END IF;

            RETURN OLD;
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_consentimentos_imutaveis
        BEFORE UPDATE OR DELETE ON consentimentos
        FOR EACH ROW EXECUTE FUNCTION consentimentos_imutaveis();
        """
    )
    op.execute(
        """
        CREATE FUNCTION ciencias_imutaveis() RETURNS trigger AS $$
        BEGIN
            IF TG_OP = 'UPDATE' THEN
                RAISE EXCEPTION 'ciencias sao imutaveis: registre uma nova ciencia'
                    USING ERRCODE = 'restrict_violation';
            END IF;

            IF EXISTS (SELECT 1 FROM usuarios WHERE id = OLD.usuario_id) THEN
                RAISE EXCEPTION 'ciencias so podem ser excluidas junto com a conta'
                    USING ERRCODE = 'restrict_violation';
            END IF;

            RETURN OLD;
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_ciencias_imutaveis
        BEFORE UPDATE OR DELETE ON ciencias
        FOR EACH ROW EXECUTE FUNCTION ciencias_imutaveis();
        """
    )
    op.execute(
        """
        CREATE FUNCTION termos_imutaveis() RETURNS trigger AS $$
        BEGIN
            IF NEW.tipo <> OLD.tipo
               OR NEW.versao <> OLD.versao
               OR NEW.titulo <> OLD.titulo
               OR NEW.resumo <> OLD.resumo
               OR NEW.vigente_desde <> OLD.vigente_desde
               OR NEW.secoes::text <> OLD.secoes::text THEN
                RAISE EXCEPTION
                    'uma versao publicada do termo nao pode ser alterada: publique uma nova versao'
                    USING ERRCODE = 'restrict_violation';
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_termos_imutaveis
        BEFORE UPDATE ON termos
        FOR EACH ROW EXECUTE FUNCTION termos_imutaveis();
        """
    )


